// Regenerates src/vendor/leafletAssets.ts from the installed leaflet package.
//
// The map screens render Leaflet inside a WebView. Loading leaflet.js/.css
// and the marker images from unpkg.com meant every map open first waited on
// a ~160KB download before anything could draw (and drew nothing at all on a
// slow or captive network). Bundling them into the app removes that wait —
// only the map tiles themselves still come from the network.
//
// Run from apps/employee-mobile:  node scripts/generate-leaflet-assets.js
const fs = require("fs");
const path = require("path");

const distDir = path.dirname(require.resolve("leaflet/dist/leaflet.js"));
const version = require("leaflet/package.json").version;

const read = (file) => fs.readFileSync(path.join(distDir, file), "utf8");
const dataUri = (file) => `data:image/png;base64,${fs.readFileSync(path.join(distDir, "images", file)).toString("base64")}`;

const js = read("leaflet.js").replace(/\/\/# sourceMappingURL=.*$/m, "");
const css = read("leaflet.css");
if (/<\/script/i.test(js) || /<\/style/i.test(css)) {
  throw new Error("Leaflet source contains a closing </script> or </style> tag and cannot be inlined as-is.");
}

const out = `// GENERATED by scripts/generate-leaflet-assets.js from leaflet@${version} — do not edit by hand.
/* eslint-disable */
export const LEAFLET_VERSION = ${JSON.stringify(version)};
export const LEAFLET_CSS = ${JSON.stringify(css)};
export const LEAFLET_JS = ${JSON.stringify(js)};
export const LEAFLET_MARKER_ICON = ${JSON.stringify(dataUri("marker-icon.png"))};
export const LEAFLET_MARKER_ICON_2X = ${JSON.stringify(dataUri("marker-icon-2x.png"))};
export const LEAFLET_MARKER_SHADOW = ${JSON.stringify(dataUri("marker-shadow.png"))};
`;

const target = path.join(__dirname, "..", "src", "vendor", "leafletAssets.ts");
fs.mkdirSync(path.dirname(target), { recursive: true });
fs.writeFileSync(target, out);
console.log(`Wrote ${path.relative(process.cwd(), target)} (leaflet@${version}, ${Math.round(out.length / 1024)}KB)`);
